import{_ as e,o as t,c as s,ag as r}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"从包豪斯到 Rams：少而更好的谱系","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/design/bauhaus-to-rams.md","filePath":"topics/design/bauhaus-to-rams.md"}'),n={name:"topics/design/bauhaus-to-rams.md"};function a(o,i,d,g,l,u){return t(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="从包豪斯到-rams-少而更好的谱系" tabindex="-1">从包豪斯到 Rams：少而更好的谱系 <a class="header-anchor" href="#从包豪斯到-rams-少而更好的谱系" aria-label="Permalink to &quot;从包豪斯到 Rams：少而更好的谱系&quot;">​</a></h1><blockquote><p>来源：en.wikipedia ⟪Bauhaus⟫、⟪International Style (architecture)⟫、⟪Less is more⟫、⟪Ludwig Mies van der Rohe⟫、⟪Hannes Meyer⟫、⟪Josef Albers⟫、⟪Dieter Rams⟫、⟪Braun (company)⟫、⟪iPod⟫、⟪Objectified⟫、⟪Rams (2018 film)⟫、⟪Mingei⟫、⟪Sori Yanagi⟫；zh.wikipedia ⟪包豪斯⟫、⟪國際風格⟫、⟪柳宗悅⟫；ja.wikipedia ⟪柳宗悦⟫、⟪民藝運動⟫；一手：Vitsœ 官网 ⟪Dieter Rams⟫ / ⟪Good design⟫（英德双语页） 链接：<a href="https://en.wikipedia.org/wiki/Bauhaus" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Bauhaus</a> ｜ <a href="https://www.vitsoe.com/de/about/good-design" target="_blank" rel="noreferrer">https://www.vitsoe.com/de/about/good-design</a> ｜ <a href="https://en.wikipedia.org/wiki/Mingei" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Mingei</a> ｜ <a href="https://zh.wikipedia.org/wiki/%E5%8C%85%E8%B1%AA%E6%96%AF" target="_blank" rel="noreferrer">https://zh.wikipedia.org/wiki/包豪斯</a> 核实状态：逐条比对维基 raw wikitext 原文与 Vitsœ 官方页；与任务预设不一致处、来源互相矛盾处均在正文标出（核实日期 2026-09-20）</p></blockquote><h2 id="先说清这条谱系的分界线" tabindex="-1">先说清这条谱系的分界线 <a class="header-anchor" href="#先说清这条谱系的分界线" aria-label="Permalink to &quot;先说清这条谱系的分界线&quot;">​</a></h2><p>极简在历史上出现过两次以上的「并行发明」，外观相似，动机相反。</p><p><strong>克制型极简</strong>：省略是手段，目的是把留下的部分做到更好——结构更清楚、材料更诚实、细节更经得起看、寿命更长。省略之后产品「增值」。 <strong>成本型极简</strong>：省略就是目的本身——减零件、减工序、减材料，把成本削掉。省略之后产品「减配」。</p><p>包豪斯→国际风格→乌尔姆→Braun / Vitsœ→Rams 这条线属于前者。它的每一次「少」都伴随一次对工艺标准、材料真实性与使用逻辑的加码；而后世大量只在视觉上模仿它的产品，把「少」当成了省钱的借口，于是同形不同质。本文只做前一支的脉络梳理，并在最后一节给出可操作的分辨判据。</p><hr><h2 id="一、包豪斯-bauhaus-1919–1933-把个人艺术意志接上批量生产" tabindex="-1">一、包豪斯（Bauhaus，1919–1933）：把个人艺术意志接上批量生产 <a class="header-anchor" href="#一、包豪斯-bauhaus-1919–1933-把个人艺术意志接上批量生产" aria-label="Permalink to &quot;一、包豪斯（Bauhaus，1919–1933）：把个人艺术意志接上批量生产&quot;">​</a></h2><p><strong>创立与三城三段</strong>。学校由 Walter Gropius（瓦尔特·格罗皮乌斯）于 <strong>1919 年 4 月 1 日</strong>在魏玛（Weimar）创立，由大公萨克森美术学院与大公萨克森工艺美术学校合并而成（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。校址与校长经历三段：魏玛 1919–1925、德绍（Dessau）1925–1932、柏林 1932–1933；校长为 Gropius 1919–1928、Hannes Meyer 1928–1930、Ludwig Mies van der Rohe 1930–1933（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。</p><p>⚠️ <strong>差异标注</strong>：zh.wikipedia ⟪包豪斯⟫ 开篇写「三任校长：1919 至 1925 年的格罗皮乌斯、1925 至 1930 年的汉斯·迈耶、1930 至 1933 年的密斯」，与 en.wikipedia 不符，也与该条目同篇后文「1928 年 4 月 1 日，格罗佩斯辞职并推荐迈耶接任」自相矛盾；以 en.wikipedia 为准，但 zh 版把 Meyer 误记到 1925 年任职这一点本身值得记录（来源：zh.wikipedia ⟪包豪斯⟫；核实 ⚠️ 该处有误）。</p><p><strong>Vorkurs 预备课程</strong>。包豪斯设计教育里最关键的发明是 <em>Vorkurs</em>（预备课程）：第一年学习设计基本要素、色彩理论，并实验各种材料与工艺，是理论加实践的务实整合（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。注意：<strong>en.wikipedia 没有 ⟪Vorkurs⟫ 独立条目</strong>（该标题返回 404），相关内容只在主条目与人物条目中，不可引不存在的来源。</p><ul><li><strong>1919–1923：Johannes Itten</strong>（伊顿）主讲，课程受 Franz Cižek 与 Friedrich Fröbel 教育思想影响，美学上受「蓝骑士」（Der Blaue Reiter）影响；伊顿于 <strong>1923 年末</strong>辞职（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。⚠️ zh.wikipedia ⟪包豪斯⟫ 说 Gropius 于 <strong>1922 年 10 月</strong>公开劝退伊顿、1923 年由纳吉接替，与 en 的「1923 年末辞职」不完全一致，两说并存（来源：zh.wikipedia ⟪包豪斯⟫；核实 ⚠️ 存疑）。</li><li><strong>1923 年后：László Moholy-Nagy</strong>（莫霍利-纳吉）接手并重写 Vorkurs，转向 Gropius 偏好的新即物主义（Neue Sachlichkeit）取向（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。</li><li><strong>Josef Albers</strong>（约瑟夫·艾伯斯）：1920 年作为学生进入伊顿的预备课程，1922 年以「彩色玻璃制作者」身份进入教师队伍；1923 年 Gropius 请他在预备课程中教 <em>Werklehre</em>（工艺学）以向新生引入手工艺原理，1925 年随迁德绍升为教授（来源：en.wikipedia ⟪Josef Albers⟫；核实 ✅）。在玻璃工作坊里 Klee 是「形式导师」（form master）、Albers 是「工艺导师」（crafts master），合作数年（同前；核实 ✅）。⚠️「Albers 主持 Vorkurs」这一常见说法未在维基找到明确表述，不采用。</li></ul><p><strong>核心宗旨</strong>：该校在设计上的著名做法，是<strong>试图把个人的艺术意志与批量生产的原则统一起来</strong>，并强调功能（原文：attempted to unify individual artistic vision with the principles of mass production and emphasis on function）；另一处表述为「主要目标之一是统一艺术、手工艺与技术」（原件：unify art, craft, and technology）（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。学校立于 <em>Gesamtkunstwerk</em>（总体艺术品）理念之上，即最终把各门艺术汇为一体（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。</p><p><strong>关键人物与师承</strong>。1919 年首批教师为 Johannes Itten、Lyonel Feininger、Gerhard Marcks 加 Gropius 本人；1920 年增 Oskar Schlemmer（主持剧场工作坊）与瑞士画家 Paul Klee（克利），1922 年增俄罗斯画家 Wassily Kandinsky（康定斯基）；此后教员阵容还包括 Gunta Stölzl、Moholy-Nagy（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。家具方向的关键人物是 <strong>Marcel Breuer</strong>（马塞尔·布劳耶）：德绍包豪斯校舍内使用他 1925–1926 年的钢管椅（瓦西里椅 Wassily Chair）；1927 年前后由 Breuer、Mart Stam 与 Mies van der Rohe 设计的钢管悬臂椅（Freischwinger）成为新材料的标志（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅ 瓦西里椅年份；zh.wikipedia ⟪包豪斯⟫ 提供悬臂椅与 Stam 的线索，核实 ✅）。Breuer 后来被 Meyer 逼迫辞去教职（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。</p><p><strong>Hannes Meyer 与分裂</strong>。Meyer（1889-11-18 – 1954-07-19），瑞士建筑师，德绍包豪斯第二任校长（1928–1930）；作为激进的功能主义者，他对学校的美学纲领毫无耐心，迫使 Herbert Bayer、Marcel Breuer 等长期教员辞职；学校在他的领导下于 <strong>1929 年</strong>首次盈利（来源：en.wikipedia ⟪Bauhaus⟫、⟪Hannes Meyer⟫；核实 ✅）。他的口号「以全民需求取代奢华需求」（<em>Volksbedarf statt Luxusbedarf</em>）与「功能图式＋经济计划才是决定性原则」的主张见 zh.wikipedia ⟪包豪斯⟫（核实 ✅）。1930 年，德绍市长 Fritz Hesse 因「涉嫌把学校经费用于共产主义事业」的丑闻解职 Meyer，并任命 Mies van der Rohe 接任（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。</p><p><strong>关闭的三种说法</strong>。这一段必须并列，因为来源彼此不一致：</p><ol><li>en.wikipedia ⟪Bauhaus⟫：柏林包豪斯在纳粹压力下于 <strong>1933 年 4 月</strong>被迫关闭；同条目另处记 1933 年盖世太保关闭柏林学校，Mies 抗议后获准重开，但随后 Mies 与教员自愿同意关闭；并明确指出学校最终是<strong>由自身领导层</strong>在纳粹压力下关闭的，此前被描绘成共产主义知识分子中心（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。</li><li>en.wikipedia ⟪Ludwig Mies van der Rohe⟫：<strong>1933 年 4 月</strong>学校遭盖世太保搜查，<strong>同年 7 月</strong>因纳粹使学校无法继续运作，Mies 与全体教员「表决」关闭包豪斯（来源：en.wikipedia ⟪Ludwig Mies van der Rohe⟫；核实 ✅）。</li><li>zh.wikipedia ⟪包豪斯⟫：1933 年 4 月德国文化部下令关闭，4 月 11 日师生被盖世太保强制驱离，<strong>8 月 10 日</strong> Mies 以经济困难为由宣布包豪斯永久解散（来源：zh.wikipedia ⟪包豪斯⟫；核实 ⚠️ 与上两说不一致）。</li></ol><p><strong>对后世的影响</strong>。</p><ul><li>设计教育：Vorkurs 式的「材料与形式基础训练」成为现代设计教育的通用模板（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。</li><li>1953 年 Max Bill 与 Inge Aicher-Scholl、Otl Aicher 在乌尔姆（Ulm）创办<strong>乌尔姆设计学院</strong>（HfG Ulm），明确「处于包豪斯传统之中」，1968 年关闭，但「乌尔姆模式」持续影响国际设计教育（来源：en.wikipedia ⟪Bauhaus⟫；核实 ✅）。这条线是包豪斯进入德国工业设计实务（含 Braun）的正门。</li><li>人员流散：Josef Albers 由当时任 MoMA 策展人的 Philip Johnson 促成，赴美国黑山学院（Black Mountain College）任教至 1949 年，1950 年转耶鲁；其黑山学生包括 Ruth Asawa、Robert Rauschenberg（来源：en.wikipedia ⟪Josef Albers⟫；核实 ✅）。Gropius、Moholy-Nagy、Mies 亦先后赴美（来源：zh.wikipedia ⟪包豪斯⟫；核实 ✅）。</li></ul><hr><h2 id="二、国际风格-international-style-1932-命名、定义与「less-is-more」的归属" tabindex="-1">二、国际风格（International Style，1932）：命名、定义与「Less is more」的归属 <a class="header-anchor" href="#二、国际风格-international-style-1932-命名、定义与「less-is-more」的归属" aria-label="Permalink to &quot;二、国际风格（International Style，1932）：命名、定义与「Less is more」的归属&quot;">​</a></h2><p><strong>命名</strong>。该词由建筑史学家 Henry-Russell Hitchcock（亨利-罗素·希区柯克）与纽约现代艺术博物馆（MoMA）建筑与设计部策展人 Philip Johnson（菲利普·约翰逊）在 MoMA 举办的建筑展中首次使用并推广（来源：en.wikipedia ⟪International Style (architecture)⟫、zh.wikipedia ⟪國際風格⟫；核实 ✅）。展览名为《现代建筑：国际主义展览》（Modern Architecture: International Exhibition），<strong>1932 年 2 月 9 日至 3 月 23 日</strong>在 MoMA 展出，随后在全美巡展（来源：zh.wikipedia ⟪國際風格⟫ 引 MoMA 官方展览页；核实 ✅）。配套出版物两件：展览图录《Modern Architecture: International Exhibition》（MoMA，1932）与著作《The International Style: Architecture Since 1922》（W. W. Norton，1932）（来源：zh.wikipedia ⟪國際風格⟫；核实 ✅）。⚠️ 任务说明中的「配套著作」表述需精确化：图录与专著是两本书，不是一本。</p><p><strong>定义特征</strong>。Hitchcock 与 Johnson 用三条原则描述 1920 年代欧洲建筑：(1) 建筑作为体量（volume）——薄板与表皮构成形体，而非实心块体；(2) 立面的规律性（regularity），而非对称；(3) 无附加装饰（no applied ornament）（来源：en.wikipedia ⟪International Style (architecture)⟫；核实 ✅）。风格表征为<strong>模数化与直线形体</strong>、<strong>无装饰与无点缀的平坦表面</strong>、内外通透的空间，以及<strong>玻璃、钢与混凝土</strong>的使用（来源：en.wikipedia ⟪International Style (architecture)⟫ 引 Britannica 等；核实 ✅）。入选 1932 年展览的代表作包括 Gropius 的法古斯工厂（Fagus，1925）与德绍包豪斯校舍（1926）、Mies 的魏森霍夫住宅展住屋（1927）、巴塞罗那德国馆（1929）、图根哈特别墅（1930）、Le Corbusier 的萨伏伊别墅（1930）（来源：zh.wikipedia ⟪國際風格⟫；核实 ✅）。</p><p><strong>「Less is more」的归属——必须写成争议</strong>。</p><ul><li>en.wikipedia ⟪Less is more⟫ 明确写道：在建筑中，这个表达<strong>常被错误地归于</strong>德裔美国建筑师 Mies van der Rohe（原文：often erroneously attributed to），该短语的实际使用早于现代主义的极简概念；<strong>德国的包豪斯运动，Gropius 与 Le Corbusier 等人，也拥抱了类似的理念</strong>（来源：en.wikipedia ⟪Less is more⟫；核实 ✅）。</li><li>同一短语的英语文本出处可上溯到更早：1855 年 Robert Browning 的戏剧独白诗《Andrea del Sarto》中就让这位文艺复兴画家说出了「less is more」（来源：en.wikipedia ⟪Less is more⟫；核实 ✅）。</li><li>但 en.wikipedia ⟪Ludwig Mies van der Rohe⟫ 又写：他常被联系到「less is more」与「God is in the details」两句格言（原文：He is often associated with his fondness for the aphorisms...）（来源：en.wikipedia ⟪Ludwig Mies van der Rohe⟫；核实 ✅）。</li><li>两者的关系应这样表述：<strong>维基百科在两个条目上口径不完全一致</strong>——人物条目说他「常与这两句格言相联系」，概念条目则说该短语「常被错误归因于他」。稳妥写法是：该短语并非密斯首创，但密斯的实践使其成为现代建筑的行业常识；1966 年 Robert Venturi 以「less is a bore」（少则无聊）作为反命题提出，可见该口号在传播上确已绑定密斯（来源：en.wikipedia ⟪Ludwig Mies van der Rohe⟫；核实 ✅）。</li></ul><hr><h2 id="三、dieter-rams-迪特·拉姆斯-把克制写成可检验的清单" tabindex="-1">三、Dieter Rams（迪特·拉姆斯）：把克制写成可检验的清单 <a class="header-anchor" href="#三、dieter-rams-迪特·拉姆斯-把克制写成可检验的清单" aria-label="Permalink to &quot;三、Dieter Rams（迪特·拉姆斯）：把克制写成可检验的清单&quot;">​</a></h2><p><strong>生平与职务</strong>。Rams 生于 <strong>1932 年 5 月 20 日</strong>，德国威斯巴登（Wiesbaden），在威斯巴登工艺美术学院学习建筑与室内设计（来源：en.wikipedia ⟪Dieter Rams⟫；核实 ✅）。<strong>1955 年</strong>加入 Braun（博朗）（来源：en.wikipedia ⟪Dieter Rams⟫；核实 ✅）。<strong>1956 年</strong>与 Hans Gugelot 一同完成 Braun SK 4 唱片机（俗称「白雪公主的棺材」），标志 Braun 设计转折点（来源：en.wikipedia ⟪Dieter Rams⟫、Vitsœ 官方页；核实 ✅）。<strong>1961 年</strong>起任 Braun 设计主管（来源：en.wikipedia ⟪Braun (company)⟫、⟪Dieter Rams⟫；核实 ✅）。⚠️ 结束年份两说：en ⟪Braun (company)⟫ 信息框记 1961–1995，en ⟪Dieter Rams⟫ 正文则提到他 1997 年退休；以「1995 年前后」表述为稳妥（来源：en.wikipedia；核实 ⚠️ 差异）。</p><p><strong>与 Vitsœ 的关系</strong>。Rams 本人原话（Vitsœ 官方页德英双语收录）：「<strong>1957 年我开始开发一套收纳系统，它构成了 1959 年成立的 Vitsœ 公司的基础。<strong>因此我的设计理念深深嵌在这家公司里。」（来源：Vitsœ 官网 ⟪Dieter Rams⟫ / ⟪Gutes Design⟫；核实 ✅）。<strong>1960 年</strong>，壁挂式 606 Universal Shelving System（606 万用置物架）上市（来源：Vitsœ 官网；核实 ✅）。官方页还给出一个常被忽略的设计动机：606 的尺度是</strong>为容纳 Braun Audio 1 紧凑音响而设定的</strong>，让家具与音响能作为一个整体并置——克制不是抽象口号，而是跨品类的尺寸协同（来源：Vitsœ 官网 ⟪Dieter Rams⟫；核实 ✅）。</p><p><strong>十项设计原则（Ten principles for good design）</strong>。Rams 在<strong>1970 年代末</strong>（Vitsœ 官方原文：in the late 1970s / in den späten 1970er Jahren）因忧虑自己所参与塑造的世界——他形容为「一片难以看透的形式、色彩与噪音的混乱」（an impenetrable confusion of forms, colours and noises）——向自己提出「我的设计是好设计吗」，答案即这份清单。<strong>这是他用于自我检视的清单，不是作品宣言</strong>（来源：Vitsœ 官网 ⟪Good design⟫ / ⟪Gutes Design⟫；核实 ✅）。德文与英文原词及中译如下（来源同前；核实 ✅）：</p><table tabindex="0"><thead><tr><th>#</th><th>德文原词</th><th>英文</th><th>中译</th></tr></thead><tbody><tr><td>1</td><td>Gutes Design ist innovativ</td><td>Good design is innovative</td><td>好的设计是创新的（创新必须与新技术同步，且绝非目的本身）</td></tr><tr><td>2</td><td>Gutes Design macht ein Produkt brauchbar</td><td>Good design makes a product useful</td><td>好的设计让产品可用（除功能外还须满足心理与审美需求）</td></tr><tr><td>3</td><td>Gutes Design ist ästhetisch</td><td>Good design is aesthetic</td><td>好的设计是美的（日常使用的器物塑造人的环境与状态）</td></tr><tr><td>4</td><td>Gutes Design macht ein Produkt verständlich</td><td>Good design makes a product understandable</td><td>好的设计让产品可被理解（最好能自我说明）</td></tr><tr><td>5</td><td>Gutes Design ist unaufdringlich</td><td>Good design is unobtrusive</td><td>好的设计是不张扬的（产品是工具，不是装饰品或艺术品，应为使用者留出自我表达的空间）</td></tr><tr><td>6</td><td>Gutes Design ist ehrlich</td><td>Good design is honest</td><td>好的设计是诚实的（不夸大、不用兑现不了的承诺操纵消费者）</td></tr><tr><td>7</td><td>Gutes Design ist langlebig</td><td>Good design is long-lasting</td><td>好的设计是长久的（避免时尚化，因此在抛弃型社会里仍能存活多年）</td></tr><tr><td>8</td><td>Gutes Design ist konsequent bis ins letzte Detail</td><td>Good design is thorough down to the last detail</td><td>好的设计是把细节做到底的（不留任意与偶然；严谨与精确即对使用者的尊重）</td></tr><tr><td>9</td><td>Gutes Design ist umweltfreundlich</td><td>Good design is environmentally-friendly</td><td>好的设计是环保的（节约资源，把物理与视觉污染降到最低）</td></tr><tr><td>10</td><td>Gutes Design ist so wenig Design wie möglich</td><td>Good design is as little design as possible</td><td>好的设计是尽可能少的设计（集中到本质，不让产品背负多余之物；「回到纯粹，回到简单」）</td></tr></tbody></table><p>⚠️ 清单<strong>总标题</strong>有两说：Vitsœ 德文官方页作 <em>Zehn Thesen für gutes Design</em>，en.wikipedia ⟪Dieter Rams⟫ 引 iF Design 作 <em>10 Grundsätze für gutes Design</em>。写引用时须注明版本（来源：Vitsœ 德语页 vs en.wikipedia；核实 ⚠️ 差异）。第 10 条的 slogan 是 <strong>「less, but better」（Weniger, aber besser，少，但更好）</strong>（来源：en.wikipedia ⟪Dieter Rams⟫；核实 ✅）。</p><p><strong>代表产品与年份</strong>（均以官方页或维基为据）：</p><ul><li><strong>Braun SK 4 唱片机，1956</strong>，设计者为 <strong>Hans Gugelot 与 Dieter Rams</strong>（来源：Vitsœ 官网；核实 ✅）。⚠️ en.wikipedia ⟪Braun (company)⟫ 有一处把 SK 4 记为「Dieter Rams 与 Herbert Lindinger」，与 Vitsœ 官方及本条目其他段落冲突，属维基内部不一致，引用时以「Gugelot + Rams」为主并注明分歧。</li><li><strong>Braun T 3 便携收音机，1958</strong>（来源：en.wikipedia ⟪iPod⟫：「iPod 的外观受 <strong>1958 年</strong>由 Dieter Rams 设计的 Braun T3 晶体管收音机启发」；核实 ✅）。⚠️ en.wikipedia ⟪Braun (company)⟫ 只笼统写作「1960 年代」，不给年份——年份以 ⟪iPod⟫ 条目为准。</li><li><strong>Braun ET 66 计算器，1987</strong>（来源：Vitsœ 官网英德双语页；核实 ✅）。⚠️ 署名分歧：Vitsœ 官方页仅署 <strong>Dietrich Lubs</strong>（for Braun），en.wikipedia ⟪Braun⟫/⟪Dieter Rams⟫ 记为 Rams 与 Lubs 合作。权威一手页更保守，故写作「Rams 团队/Dietrich Lubs 主导」并标注。</li><li><strong>Vitsœ 606 万用置物架，1960</strong>（来源：Vitsœ 官网；核实 ✅）；<strong>Vitsœ 620 座椅系统，1962</strong>（来源：Vitsœ 官网；核实 ✅）。</li><li>官方页另给出可交叉校验的年份：L 2 扬声器 1958、TP 1 收音/唱机组合 1959、RT 20 台式收音机 1961、T 1000 世界收音机 1963、T 2 圆柱打火机 1968、MPZ 21 电动柑橘榨汁机 1972（来源：Vitsœ 官网；核实 ✅）。</li></ul><p><strong>与 Apple / Jony Ive 的关联，与两部纪录片</strong>。</p><ul><li>en.wikipedia ⟪Dieter Rams⟫ 设有「Apple」专节：Rams 的设计影响了 Apple 的产品，其中 2007 年 iPhone 的收音机界面明显效法 Braun 的 T 3 设计（来源：en.wikipedia ⟪Dieter Rams⟫；核实 ✅）。</li><li>2011 年出版的 Rams 专著由 Apple 时任设计负责人 <strong>Jony Ive</strong> 撰写序言（来源：en.wikipedia ⟪Dieter Rams⟫；核实 ✅）。</li><li>另有广泛流传的细节称 Rams 曾把自己的 iPhone 寄给 Apple 并表示「这是第一款遵循我的设计原则做出的产品」，该说法出自设计博物馆（Design Museum）材料，属二手引述（来源：en.wikipedia ⟪Dieter Rams⟫ 引 Design Museum；核实 ⚠️ 二手）。</li><li><strong>《Objectified》（2009）</strong>：Gary Hustwit 执导的长片纪录片，讨论日常人造物及其设计者，2009 年 3 月 14 日于西南偏南（SXSW）首映，是 Hustwit「设计三部曲」的第二部（来源：en.wikipedia ⟪Objectified⟫；核实 ✅）。</li><li><strong>《Rams》（2018）</strong>：Gary Hustwit 执导的纪录片，2016 年经 Kickstarter 众筹启动，2018 年秋上映（维基信息框记 2018 年 11 月 28 日），配乐由 Brian Eno 创作；影片讨论 Rams 对现代设计的影响、他在 Braun 与 Vitsœ 的工作，以及他对可持续性与消费主义的看法（来源：en.wikipedia ⟪Rams (2018 film)⟫；核实 ✅）。⚠️ 任务说明里的「Objectified 2009、Rams 2018」年份经核实无误。</li></ul><hr><h2 id="四、日本民艺运动-mingei-同向的另一条克制" tabindex="-1">四、日本民艺运动（Mingei）：同向的另一条克制 <a class="header-anchor" href="#四、日本民艺运动-mingei-同向的另一条克制" aria-label="Permalink to &quot;四、日本民艺运动（Mingei）：同向的另一条克制&quot;">​</a></h2><p><strong>「民艺」一词的年份（任务重点核实项）</strong>。ja.wikipedia ⟪民藝運動⟫ 记载：<strong>1925 年末</strong>，柳宗悦与滨田庄司、河井宽次郎一起，把「民衆的工藝」缩略成新词「民藝」并开始使用（原文：1925年の末、柳は濱田庄司、河井寛次郎とともに「民衆的工藝」を略した「民藝」という新語を作り、使い始めた）（来源：ja.wikipedia ⟪民藝運動⟫；核实 ✅）。ja.wikipedia ⟪柳宗悦⟫ 说 1925 年起他开始使用「民藝」一词（核实 ✅）；en.wikipedia ⟪Mingei⟫ 与 zh.wikipedia ⟪民艺⟫ 亦记为 1925 年（核实 ✅）。<strong>三语一致：1925 年，非 1926 年</strong>。 <strong>1926 年</strong>，柳宗悦、富本宪吉、滨田庄司、河井宽次郎四人联名发表《日本民藝美術館設立趣意書》（来源：ja.wikipedia ⟪柳宗悦⟫；核实 ✅）——注意：署名者 4 人，比 1925 年造词时多了富本宪吉。<strong>1936 年</strong>日本民藝館在东京目黑区驹场设立（来源：en.wikipedia ⟪Mingei⟫、zh.wikipedia ⟪柳宗悅⟫；核实 ✅）。</p><p><strong>人物与著作</strong>。柳宗悦（Yanagi Sōetsu，1889-03-21 – 1961-05-03，en.wikipedia 给出的生卒日），日本民艺运动创始人与美学家、日本民艺馆创办人（来源：en.wikipedia ⟪Yanagi Sōetsu⟫；核实 ✅）。同道：河井宽次郎（陶艺）、滨田庄司（陶艺）、芹泽銈介（型染）——ja.wikipedia 记河井与滨田为柳「生涯の同志」，芹泽銈介则参与民艺运动并为柳的著作做装帧（来源：ja.wikipedia ⟪柳宗悦⟫、en.wikipedia ⟪Keisuke Serizawa⟫；核实 ✅）。其代表论著《工艺之道》（『工藝の道』）的核心句被引为「<strong>用与美相结合者即工艺</strong>」（原文：用と美が結ばれるものが工芸である）；⚠️ 该书年份两说：ja.wikipedia 正文记 1928 年刊、同页著作列表记 1929 年，写作时须标注（来源：ja.wikipedia ⟪柳宗悦⟫；核实 ⚠️ 年份差异，引语 ✅）。英文世界主要通过文集 <em>The Unknown Craftsman</em>（《无名工匠》）接触其思想（来源：en.wikipedia ⟪Shibui⟫、⟪Mingei⟫；核实 ✅）。</p><p><strong>「用之美」与「无心之美」</strong>。</p><ul><li>「用之美」是柳宗悦在中文语境的固定译法，zh.wikipedia ⟪柳宗悅⟫ 即写「強調民藝品的實用價值，提倡『用之美』」（来源：zh.wikipedia ⟪柳宗悅⟫；核实 ✅）；en.wikipedia ⟪Mingei⟫ 记为「celebrated the beauty of everyday objects」（歌咏日常物之美）（核实 ✅）。其含义是：美不是装饰出来的附加物，而是<strong>在实用与日常使用中被磨出来的品质</strong>——正因为不为美而造，美才出现。</li><li>⚠️ <strong>「无心之美」未能核实为固定术语</strong>：在 ja.wikipedia ⟪柳宗悦⟫、⟪民藝運動⟫ 中检索「無心」为 0 命中；本文不把它当作柳的原文表述引用。可替代且有来源的相邻概念是：ja.wikipedia ⟪民藝運動⟫ 的「<strong>無私の工人</strong>」（无私的工匠），以及 en.wikipedia ⟪Mingei⟫ 转述的 **tarikidō（他力道，即依靠他力/倾空自我）**与「直観」（intuition）——柳认为无名工匠的「无我」状态使器物的美超出个人算计（来源：ja.wikipedia ⟪民藝運動⟫、en.wikipedia ⟪Mingei⟫；核实 ✅ 相关概念存在 / ⚠️「无心之美」四字未核实）。</li></ul><p><strong>与 Rams 的对照表</strong>（本表为本文综合，左栏见上述来源，右栏见第三节）：</p><table tabindex="0"><thead><tr><th>维度</th><th>日本民艺运动（1925– ）</th><th>Dieter Rams（1955– ）</th></tr></thead><tbody><tr><td>生产者</td><td>无名工匠（The Unknown Craftsman），个体可被略去</td><td>名师设计，署名与作者性明确（Rams/Gugelot/Lubs）</td></tr><tr><td>用途定位</td><td>实用与日常，为生活现场而造</td><td>功能与工业，为批量生产与大规模市场而造</td></tr><tr><td>美的生成机制</td><td>偶然性与自然（釉变、手痕、无我/他力），美是副产品</td><td>标准化（网格、模数、可互换零件），美是被检验过的结果</td></tr><tr><td>对「少」的态度</td><td>少因不使用多余装饰、不做无谓加工</td><td>少因集中本质，且被写进十条自我检视清单</td></tr><tr><td>时间观</td><td>器物在长期使用中变美（用之美）</td><td>产品在长期使用中不变丑（第 7 条：长存）</td></tr><tr><td>与商业的关系</td><td>反工业化量产、反对以新奇取胜</td><td>深度嵌入企业（Braun）与自有品牌（Vitsœ），以系统化取胜</td></tr></tbody></table><p><strong>桥接人物：柳宗理</strong>。柳宗悦长子 <strong>柳宗理（Sōri Yanagi，1915-06-29 – 2011-12-25）</strong> 是日本产品设计师，代表作 Butterfly Stool（蝴蝶凳，<strong>1954</strong>）与 Elephant Stool（1954）；en.wikipedia 对他的定位是「完全意义上的现代主义者，把简洁与实用同日本传统手工艺元素融合起来」（a full-blown modernist who merged simplicity and practicality with elements of traditional Japanese crafts），并受 Le Corbusier 与 Charlotte Perriand 影响（来源：en.wikipedia ⟪Sori Yanagi⟫；核实 ✅）。他使民艺的「用之美」不必停在反工业的立场上，而能与现代产品设计合流——这是本文谱系的东方支点。</p><hr><h2 id="五、为什么要区分这支-省略后增值-vs-省略能力" tabindex="-1">五、为什么要区分这支：省略后增值 vs 省略能力 <a class="header-anchor" href="#五、为什么要区分这支-省略后增值-vs-省略能力" aria-label="Permalink to &quot;五、为什么要区分这支：省略后增值 vs 省略能力&quot;">​</a></h2><p>把 Rams 式的克制与「性冷淡风」「极简风」混为一谈，是这条谱系最常见的误读。二者共享外观，动机相反：</p><ul><li><strong>克制型极简是「省略后增值」</strong>：省掉的是视觉噪音与冗余结构，省不掉的是成本与工序——第 8 条「细节一贯到底」要求不留任意与偶然，第 9 条要求环保，第 3 条要求「只有做得好的东西才能是美的」（only well-executed objects can be beautiful）。省略之后，剩下的每个零件承担更多责任，因此<strong>单位成本往往上升</strong>（来源：Vitsœ 官网 ⟪Good design⟫ 第 3、8、9 条；核实 ✅）。</li><li><strong>成本型极简是「省略能力」</strong>：省掉的是能力本身——可维修性、材料等级、公差控制、说明与配件的完整性。它借用克制型极简的语汇，把「少」变成降配的辩护词。</li></ul><p><strong>可判断的判据</strong>（可直接用于产品评价，本文归纳）：</p><ol><li><strong>减法的对象</strong>：减掉的是装饰与噪音（克制型），还是功能、结构强度与可维修性（成本型）？看剖切面与内部结构，而不是看外观。</li><li><strong>剩下的部分是否被加码</strong>：克制型会把省下的资源投到铰链、转轴、公差、材料一致性与配件寿命上；成本型会在这些看不见的地方同步缩水。</li><li><strong>是否留有可被检验的规则</strong>：克制型是可被写下来的（Vorkurs 的材料训练、国际风格的三条原则、Rams 的十条清单），可被第三方复核；成本型只有风格指令，没有可复核的标准。</li><li><strong>时间上的行为</strong>：克制型尽量避免时尚化，因而长年不变丑、且能长期供应配件（Vitsœ 至今供应 606 的部件，官方口号是「从小处开始，逐步添加，搬家时带走」）（来源：Vitsœ 官网；核实 ✅）；成本型靠年抛与改款制造购买理由。</li><li><strong>署名与责任归属</strong>：克制型通常能追溯到具体的人与可核查的年份（SK 4 = 1956、ET 66 = 1987），因为要为长期品质承诺负责；成本型趋于匿名，以规避责任。</li><li><strong>是否跨品类协同</strong>：克制型把「少」兑现为系统（606 的尺度按 Braun Audio 1 设定，使家具与音响成为整体），成本型把每个品类推向极致低价而互不相干（来源：Vitsœ 官网；核实 ✅）。</li></ol><p>一句话：<strong>看它省掉的是噪音还是能力</strong>。省掉噪音的，越用越值；省掉能力的，越用越薄。</p><hr><p>关键词：极简主义、判据、包豪斯、国际风格、预备课程、少即是多、少而更好、十项原则、民艺运动、用之美、无名工匠、柳宗理 关联：</p><ul><li><code>topics/design/minimalism-death-of-detail.md</code>：本谱系是主文档第六节「less, but better」判据的历史展开（克制型极简的来源）</li><li><code>topics/quality-products/</code>：Rams 与 Braun/Vitsœ 把克制制度化为一套交付标准，与「德国制造」的精密制造同源</li><li><code>topics/design/less-but-better-engineering.md</code>：Rams「十原则＝可核对清单」正是工程判据清单的历史先例（把美学判断转成验收条款）</li><li><code>topics/philosophy/</code>：民艺「不为美而造才有美」与「无心之美」是一支反意图论的美学立场</li><li><code>topics/materials/</code>：606 置物架的长期供应与 Rams 第 9 条（环保）是耐用性与可维修设计的前置文本</li></ul><blockquote><p>整理日期：2026-09-20</p></blockquote>',56)])])}const k=e(n,[["render",a]]);export{h as __pageData,k as default};
